#!/usr/bin/env bash
# Regression test for tests/check_line_citations.sh. The gate's value is the pair
# it can prove — the named file exists and the quoted line(s) sit inside it — so
# the boundary of each half needs pinning: an off-by-one that slips through makes
# the gate decorative, and a too-eager EOF test reddens every docstring that quotes
# the last line of a file without a trailing newline. Contract pinned here.
#
# Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later

set -u

root=$(git rev-parse --show-toplevel 2>/dev/null) || {
    printf 'SKIP  line-citation self-test (no git checkout)\n'
    exit 125
}
check=$root/tests/check_line_citations.sh
if [ ! -f "$check" ]; then
    printf 'FAIL  %s is missing\n' "$check"
    exit 1
fi

# Not a bare /tmp: MSYS child shells default TMP/TEMP to /tmp, and native
# git.exe then maps a /tmp argument to C:\tmp while bash sees %TEMP%.
if command -v cygpath >/dev/null 2>&1 && [ -n "${USERPROFILE:-}" ]; then
    tmpbase=$(cygpath -w "$USERPROFILE")
else
    tmpbase=${TMP:-.}
fi
tmp=$(mktemp -d "$tmpbase/pime-line-citations-selftest.XXXXXX")
sandbox=$tmp/repo
mkdir -p "$sandbox/python" "$sandbox/tests" "$sandbox/docs"

cleanup() {
    rm -rf "$tmp"
}
trap cleanup EXIT

git -C "$sandbox" init -q >/dev/null

failures=0

# expect <want-rc> <name> — runs the gate in the sandbox and matches its code.
expect() {
    local want="$1" name="$2" out got
    out=$(cd "$sandbox" && bash "$check" 2>&1)
    got=$?
    if [ "$got" -ne "$want" ]; then
        printf 'FAIL  %s (rc %s, want %s)\n%s\n' "$name" "$got" "$want" "$out"
        failures=$((failures + 1))
    fi
}

# expect_named <want-rc> <name> <needle> — also requires the file to be named.
expect_named() {
    local want="$1" name="$2" needle="$3" out got
    out=$(cd "$sandbox" && bash "$check" 2>&1)
    got=$?
    if [ "$got" -ne "$want" ]; then
        printf 'FAIL  %s (rc %s, want %s)\n%s\n' "$name" "$got" "$want" "$out"
        failures=$((failures + 1))
        return
    fi
    case "$out" in
        *"$needle"*) : ;;
        *) printf 'FAIL  %s: output does not name %s\n%s\n' "$name" "$needle" "$out"
           failures=$((failures + 1)) ;;
    esac
}

reset_index() {
    local f
    for f in $(git -C "$sandbox" ls-files); do
        rm -f "$sandbox/$f"
    done
    git -C "$sandbox" rm -q -r --cached . >/dev/null 2>&1 || true
}

# Each case starts from an empty index: the gate reads the whole staged tree, so a
# stray citation from the previous case would decide the next one's code.
target3() {
    printf 'first\nsecond\nthird\n' > "$sandbox/python/target.py"
}

# In-range citations of a real file: the pair the gate exists to prove.
reset_index
target3
printf 'x = 1  # python/target.py:1-3 and python/target.py:3\n' > "$sandbox/tests/test_ok.py"
git -C "$sandbox" add python/target.py tests/test_ok.py
expect 0 'in-range citations pass'

# Past the last line, and the offending file is the thing named.
reset_index
target3
printf 'x = 1  # python/target.py:9\n' > "$sandbox/tests/test_far.py"
git -C "$sandbox" add python/target.py tests/test_far.py
expect_named 1 'a number past EOF fails and names the citing file' 'tests/test_far.py'

# A missing target is broken even when the number is small.
reset_index
printf 'x = 1  # python/gone.py:1\n' > "$sandbox/tests/test_gone.py"
git -C "$sandbox" add tests/test_gone.py
expect_named 1 'a missing target fails and names its citation' 'python/gone.py:1'

# The bare continuation form follows the named file on the same line, in both
# directions of the range check.
reset_index
target3
printf 'x = 1  # python/target.py:1 writes the field, and :2-3 the rest\n' \
    > "$sandbox/tests/test_bare.py"
git -C "$sandbox" add python/target.py tests/test_bare.py
expect 0 'a bare :N continuation follows the same-line file'

reset_index
target3
printf 'x = 1  # python/target.py:1 and :9\n' > "$sandbox/tests/test_bare_far.py"
git -C "$sandbox" add python/target.py tests/test_bare_far.py
expect_named 1 'a bare :N past EOF fails' 'python/target.py:9'

# The last line of a file without a trailing newline is still a line.
reset_index
printf 'a\nb\nc' > "$sandbox/python/tight.py"
printf 'x = 1  # python/tight.py:3\n' > "$sandbox/tests/test_tight.py"
git -C "$sandbox" add python/tight.py tests/test_tight.py
expect 0 'the unwrapped final line counts'

# Zero as a line number is not a line.
reset_index
target3
printf 'x = 1  # python/target.py:0\n' > "$sandbox/tests/test_zero.py"
git -C "$sandbox" add python/target.py tests/test_zero.py
expect 1 'line zero is out of range'

# A bare basename resolves when exactly one tracked file carries that name, which
# is how the docstrings already write it.
reset_index
target3
printf 'x = 1  # target.py:2\n' > "$sandbox/tests/test_suffix.py"
git -C "$sandbox" add python/target.py tests/test_suffix.py
expect 0 'a unique basename resolves'

# Two tracked files sharing a name leave the citation unreadable: the gate says so
# instead of guessing a target.
reset_index
target3
mkdir -p "$sandbox/python/other"
printf 'a\nb\n' > "$sandbox/python/other/target.py"
printf 'x = 1  # target.py:2\n' > "$sandbox/tests/test_ambiguous.py"
git -C "$sandbox" add python/target.py python/other/target.py tests/test_ambiguous.py
expect_named 1 'a duplicated basename is reported ambiguous' 'ambiguous citation'

# A dated snapshot pins only the existence of its target: the numbering it quoted
# belongs to its own reading, which a later refactor legitimately moves.
reset_index
target3
mkdir -p "$sandbox/docs/research"
printf 'See target.py:9 for the field.\n' > "$sandbox/docs/research/snapshot.md"
git -C "$sandbox" add python/target.py docs/research/snapshot.md
expect 0 'a dated snapshot past EOF still passes'

reset_index
printf 'See python/gone.py:1\n' > "$sandbox/docs/research/gone.md"
git -C "$sandbox" add docs/research/gone.md
expect_named 1 'a dated snapshot still needs a live target' 'python/gone.py:1'

# The vendored and pinned trees stay silent: the submodule ships uninitialized.
reset_index
mkdir -p "$sandbox/python/python3"
printf '# cites python/python3/lib/site-packages/x.py:999\n' > "$sandbox/python/python3/doc.py"
printf '# cites libchewing/src/x.c:9999\n' > "$sandbox/tests/test_pinned.py"
git -C "$sandbox" add python/python3/doc.py tests/test_pinned.py
expect 0 'vendored and pinned trees stay silent'

# The self-test of the gate is read for nothing: the names it writes exist only in
# the sandbox that test builds, so they must not redd the tree. Without the skip the
# 99 below would fail against the three-line target.
reset_index
target3
printf 'x = 1  # python/target.py:1\n' > "$sandbox/tests/test_ok.py"
printf 'x = 1  # python/target.py:99\n' > "$sandbox/tests/check_line_citations_test.sh"
git -C "$sandbox" add python/target.py tests/test_ok.py tests/check_line_citations_test.sh
expect 0 'the fixture file stays out of the scan'

# A tree with no citation at all is not applicable rather than a vacuous pass.
reset_index
printf 'x = 1\n' > "$sandbox/tests/test_plain.py"
git -C "$sandbox" add tests/test_plain.py
expect 125 'a citation-free tree is not applicable'

# Outside a git checkout the gate is not applicable, not a failure.
nowork=$tmp/nowork
mkdir -p "$nowork"
out=$(cd "$nowork" && bash "$check" 2>&1)
got=$?
if [ "$got" -ne 125 ]; then
    printf 'FAIL  outside a checkout (rc %s, want 125)\n%s\n' "$got" "$out"
    failures=$((failures + 1))
fi

printf '%d failed\n' "$failures"
[ "$failures" -eq 0 ]
